record.field:
# Hämta projektet
project = env['project.project'].search([('name', '=', 'Invärldsbevakning SWOT-analys')], limit=1)
if not project:
    raise UserError("Projektet finns inte.")

# Hämta eller skapa fasen "Weaknesses" för projektet
stage = env['project.task.type'].search([
    ('name', '=', 'Weaknesses'),
    ('project_ids', 'in', project.id)
], limit=1)
if not stage:
    stage = env['project.task.type'].create({'name': 'Weaknesses', 'project_ids': [(4, project.id)]})

# Hämta quadrant för "Weaknesses" i detta projekt
quadrant = env['project.task.quadrant'].search([
    ('project_id', '=', project.id),
    ('name', '=', 'Weaknesses')
], limit=1)

# Hämta AI-svar (anpassa message_invoke om det behövs)
result = quest.build(session=session, message="", record=project).invoke(message_invoke)
answer = quest.get_last_ai_message_content(result)

# Loopa igenom Weakness 1 och 2 (ändra antalet vid behov)
for i in range(1, 3):
    key = f"Weakness {i}"
    start = answer.find(key)
    end = answer.find(f"Weakness {i+1}") if i < 2 else len(answer)
    section = answer[start:end].strip() if start != -1 else ""
    lines = section.split('\n')
    namn = key
    for line in lines:
        if line.lower().startswith('namn:'):
            namn = line.split(':', 1)[1].strip()
            break
    coord = ""
    for line in lines:
        if '[' in line and ']' in line:
            coord = line[line.find('['):line.find(']')+1]
            break

    # Skapa eller uppdatera task för Weakness
    task = env['project.task'].search([
        ('project_id', '=', project.id),
        ('name', '=', namn)
    ], limit=1)
    if not task:
        task = env['project.task'].create({
            'name': namn,
            'project_id': project.id,
            'stage_id': stage.id,
        })
    values = {'description': self.markdown2html(section)}
    if coord:
        values['coordinate'] = coord
    if quadrant:
        values['quadrant'] = quadrant.id
    task.write(values)

